import{_ as r,l as o,o as e,c as s,v as t,p as l,x as n,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"ns-3 与 mininet","description":"","frontmatter":{"title":"ns-3 与 mininet","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/network-simulation.md","filePath":"cs/network-simulation.md","lastUpdated":1789023840000}'),h={name:"cs/network-simulation.md"};function m(u,a,_,B,E,f){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="ns-3-与-mininet" tabindex="-1">ns-3 与 mininet <a class="header-anchor" href="#ns-3-与-mininet" aria-label="Permalink to &quot;ns-3 与 mininet&quot;">​</a></h1><div class="epigraph"><p>ns-3 是离散事件仿真，时间与丢包完全可控；Mininet 用网络命名空间搭真实内核栈的迷你拓扑，保真协议、难保线速。</p><footer>—— 据 ns-3 手册；Lantz et al., Mininet, 2010 整理</footer></div><p><a href="/cs/packet-capture">抓包</a> 在真网上贵。<a href="/cs/packet-capture">上一课</a> 留下「如何复现」。缺口是<strong>仿真 vs 仿真式仿真（emulation）</strong>。本课不把 Reactor 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>incast、AQM、BGP 收敛在生产上难复现。ns-3：事件队列推进虚拟时间，可插传播延迟与错误模型，协议是模型或真实栈移植。Mininet：Linux netns + veth + OVS，跑真 TCP，用 tc 限速，CPU 共享则时间戳假。卫星 RTT 在 ns-3 里设数即可。P4 有 BMv2 仿真点名。</p><p>不要把仿真曲线当 SLA。</p><p><span class="marginnote">Mininet 2010。ns-3 是科研常用。本课不教安装。</span></p><h3 id="保真哪一层要先选" tabindex="-1">保真哪一层要先选 <a class="header-anchor" href="#保真哪一层要先选" aria-label="Permalink to &quot;保真哪一层要先选&quot;">​</a></h3><p>ns-3 控时间；Mininet 保真内核栈不保真线速。曲线不是 SLA。随机种子要记。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：数学分析 / ns-3 / Mininet / 试验床。画：问题选工具。与 Clos 拓扑：Mininet 能搭，但脊线速假。</p>',11)),(e(),l(d,null,{default:n(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NS3%5B%22%E7%A6%BB%E6%95%A3%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20CTRL%5B%22%E5%8F%AF%E6%8E%A7%E6%97%B6%E9%97%B4%22%5D%0A%20%20MINI%5B%22netns%20%E4%BB%BF%E7%9C%9F%22%5D%20--%3E%20REAL%5B%22%E7%9C%9F%E5%86%85%E6%A0%B8%E6%A0%88%22%5D%0A%20%20REAL%20--%3E%20CPU%5B%22%E5%8F%97%E4%B8%BB%E6%9C%BA%20CPU%20%E9%99%90%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>抓包在 Mininet 里方便。iperf 在仿真里量的是模型 \\(C\\)。SDN 控制器可接 Mininet。DNS TTL 可加速测试。不要用仿真证明互联网政策。</p><p>随机种子要记，否则不可复现。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 OMNeT++ 的全部。Reactor/Proactor 是下一课。后课默认：仿真控变量；Mininet 保真栈不保真速率。</p><p>把 1000 台主机仿真在笔记本上会自己成为瓶颈。</p><p>上一课留下的缺口在本课收口；「ns-3 与 mininet」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/reactor-proactor">Reactor / Proactor</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ns-3：虚拟时间，模型清晰。</li><li>Mininet：真协议栈，资源共享。</li><li>选工具看要保真哪一层。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：ns-3；Lantz et al., 2010。</li></ul>',10))])}const P=r(h,[["render",m]]);export{T as __pageData,P as default};
